/* ================= 工具 ================= */
const $ = (s, el) => (el || document).querySelector(s);
const $$ = (s, el) => Array.from((el || document).querySelectorAll(s));
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const rand = (a, b) => a + Math.random() * (b - a);
const ri = (a, b) => Math.floor(rand(a, b + 1));
const shuffle = (arr) => { const a = arr.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
const fmtTime = (s) => (s < 60 ? s + ' 秒' : Math.floor(s / 60) + ' 分 ' + (s % 60 ? (s % 60) + ' 秒' : ''));
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const debounce = (fn, ms) => { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; };

/* ================= 存储 ================= */
const Store = {
  get(k, d) { try { const v = localStorage.getItem('cnp_' + k); return v === null ? d : JSON.parse(v); } catch (e) { return d; } },
  set(k, v) { try { localStorage.setItem('cnp_' + k, JSON.stringify(v)); } catch (e) { /* ignore */ } },
};

/* ================= 音效引擎（WebAudio 合成，手势后初始化） ================= */
const Sound = (() => {
  let ctx = null, master = null, enabled = true;
  function init() {
    if (ctx) { resume(); return; }
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      ctx = new AC();
      master = ctx.createGain();
      master.gain.value = 0.4;
      master.connect(ctx.destination);
    } catch (e) { /* ignore */ }
  }
  function resume() { if (ctx && ctx.state === 'suspended') ctx.resume(); }
  function tone(freq, dur, type, vol, when, slide) {
    if (!ctx || !master || !enabled) return;
    const t = ctx.currentTime + (when || 0);
    const o = ctx.createOscillator(), g = ctx.createGain();
    o.type = type || 'sine';
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(40, slide), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(vol, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(master);
    o.start(t); o.stop(t + dur + 0.06);
  }
  return {
    init, resume,
    isOn() { return enabled; },
    setOn(v) { enabled = !!v; Store.set('sound', enabled); },
    toggle() { this.setOn(!enabled); return enabled; },
    click() { tone(660, 0.05, 'triangle', 0.22); },
    ok() { tone(523, 0.09, 'sine', 0.35); tone(659, 0.09, 'sine', 0.35, 0.085); tone(784, 0.13, 'sine', 0.32, 0.17); },
    okCombo() { tone(523, 0.06, 'sine', 0.34); tone(659, 0.06, 'sine', 0.34, 0.06); tone(784, 0.06, 'sine', 0.34, 0.12); tone(1046, 0.2, 'sine', 0.4, 0.18); },
    bad() { tone(220, 0.2, 'sawtooth', 0.22, 0, 110); },
    tick() { tone(880, 0.045, 'square', 0.1); },
    place() { tone(440, 0.08, 'triangle', 0.32, 0, 660); },
    win() { [523, 659, 784, 1046].forEach((f, i) => tone(f, 0.2, 'triangle', 0.32, i * 0.13)); tone(1318, 0.45, 'triangle', 0.24, 0.55); },
    /* iOS 侧边静音检测：播放探测音并采样，静音则回调 true */
    probeSilence(cb) {
      if (!ctx || !master || !enabled) return cb(false);
      try {
        const a = ctx.createAnalyser();
        a.fftSize = 64;
        master.connect(a);
        const o = ctx.createOscillator(), g = ctx.createGain();
        o.frequency.value = 440;
        g.gain.value = 0.25;
        o.connect(g); g.connect(master);
        o.start();
        setTimeout(() => {
          const d = new Uint8Array(a.frequencyBinCount);
          a.getByteFrequencyData(d);
          let any = false;
          for (let i = 0; i < d.length; i++) if (d[i] > 0) { any = true; break; }
          try { o.stop(); master.disconnect(a); } catch (e) { /* ignore */ }
          cb(!any);
        }, 600);
      } catch (e) { cb(false); }
    },
  };
})();

