/* ================= UI 基础设施 ================= */
function toast(msg, isAch, dur) {
  const t = $('#toast');
  t.textContent = msg;
  t.className = isAch ? 'ach show' : 'show';
  clearTimeout(t._tm);
  t._tm = setTimeout(() => t.classList.remove('show'), dur || 2400);
}

function openOverlay(html, sticky) {
  closeOverlay();
  const host = $('#sheetHost');
  host.innerHTML = '<div class="overlay"><div class="panel">' + html + '</div></div>';
  const ov = $('.overlay', host);
  if (sticky) ov.dataset.sticky = '1';
  ov.addEventListener('pointerdown', (e) => {
    if (e.target === ov && !ov.dataset.sticky) closeOverlay();
  });
  const cx = $('.close-x', ov);
  if (cx) cx.addEventListener('click', closeOverlay);
  return ov;
}
function closeOverlay() {
  $('#sheetHost').innerHTML = '';
  $('#modalHost').innerHTML = '';
}
