  lives: -1, timeUsed: 0, t0: 0, minReact: 999,
  seq: [], idx: 0, player: 0, scores: [0, 0], combos: [0, 0], livesP: [-1, -1],
  hintsUsed: 0, hintLvl: 0, curTarget: null,
  locked: false, rafTimer: null, blitzEnd: 0,
