    $('#gameView').classList.remove('hidden');
    $('.top-actions').classList.add('hidden');
    $('#btnBrand').classList.add('hidden');
    if (this.mode !== 'puzzle') ChinaMap.setMapFill(S.mapFill);
    $('#qbMode').textContent = mode === 'puzzle'
