    ChinaMap.setInteraction({ labels: false, hover: false, onClick: null, puzzleBase: 'normal' });
    // 复位拼图舞台，避免上一模式的布局状态残留（如 puzzleStage 被拼图隐藏）
    const pz = $('#puzzleStage');
    pz.classList.remove('hidden');
    pz.classList.remove('has-sides');
    pz.classList.remove('has-minis');
    pz.classList.remove('full');
    this._show('sideL', false);
    this._show('sideR', false);
    this._show('miniL', false);
