/* ================= 模式启动页 ================= */
function quizSumChips(p) {
  const rg = '范围：' + (S.region === 'all' ? '全国' : S.region);
  if (p === 'blitz') return '<span class="chip">时长 ' + S.blitzTime + ' 秒</span><span class="chip">' + rg + '</span><span class="chip">无生命限制</span>';
  if (p === 'duel') return '<span class="chip">每人 ' + S.duelRounds + ' 题</span><span class="chip">' + rg + '</span><span class="chip">生命 ' + (S.lives < 0 ? '无限' : S.lives) + '</span>';
  return sumChips();
}
function showModeStart(id) {
  let m = MODES.find((x) => x.id === id);
  if (id === 'outline') m = { name: '轮廓识别', tag: '看轮廓选省名 · 四选一', hue: 'm4',
    icon: '<svg viewBox="0 0 24 24"><path d="M6 4h9v5H6zM15 9h3a2 2 0 0 1 2 2v7a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2v-3"/><path d="M9 15h4v4"/></svg>' };
  const mTitle = (id === 'quiz' && S.gameplay === 'duel') ? '识图对战' : (id === 'outline' ? (S.outlineGame === 'duel' ? '轮廓对战' : '轮廓识别') : m.name);
  const mSub = (id === 'quiz' && S.gameplay === 'duel') ? '双人轮流作答 · 比拼正确率与手速' : (m.tag + ' · 点击开始后自动切换视图');
  let chips = '';
  let names = '';
  if (id === 'explore') chips = '<span class="chip">自由浏览 · 无计分</span>';
  else if (id === 'puzzle') {
    names = `
      <div class="set-label">玩法</div>
      <div class="chip-row" id="pgChips">
        ${[['solo', '单人拼图'], ['race', '同图竞赛'], ['split', '异图竞赛']].map(([p, n]) => `<button class="chip${S.puzzleGame === p ? ' on' : ''}" data-p="${p}">${n}</button>`).join('')}
      </div>
      <div id="pgParams" class="chip-row" style="margin-top:8px"></div>
      <div class="sum-chips" id="pgSum">${puzzleSumChips()}</div>
      <div id="pgNames" class="${['race', 'split'].includes(S.puzzleGame) ? '' : 'hidden'}">
        <div class="set-label">玩家昵称</div>
        <input id="duelName1" class="name-input" maxlength="8" placeholder="玩家一" value="${esc(S.p1)}">
        <input id="duelName2" class="name-input" maxlength="8" placeholder="玩家二" value="${esc(S.p2)}">
      </div>`;
  }
  else if (id === 'outline') {
    if (S.outlineGame === 'duel') {
      names = `
        <div class="set-label">玩法</div>
        <div class="chip-row"><span class="chip on">轮廓对战</span></div>
        <div class="sum-chips"><span class="chip">每人 ${S.outlineDuelRounds} 题</span><span class="chip">四选一</span></div>
        <div class="set-label">计分规则</div>
        <div class="chip-row" id="olMode">
          <button class="chip${S.outlineMode==='accuracy'?' on':''}" data-v="accuracy">正确率模式</button>
          <button class="chip${S.outlineMode==='score'?' on':''}" data-v="score">计分模式</button>
        </div>
        <div id="olScoreParams"></div>
        <div class="set-label">玩家昵称</div>
        <input id="duelName1" class="name-input" maxlength="8" placeholder="玩家一" value="${esc(S.p1)}">
        <input id="duelName2" class="name-input" maxlength="8" placeholder="玩家二" value="${esc(S.p2)}">`;
    } else {
      names = `
        <div class="set-label">题数</div>
        <div class="chip-row" id="olRounds">
          ${[10, 15, 20, 25].map((v) => `<button class="chip${S.outlineRounds === v ? ' on' : ''}" data-v="${v}">${v} 题</button>`).join('')}
        </div>
        <div class="sum-chips"><span class="chip">四选一</span><span class="chip">不限时</span></div>`;
    }
  }
  else if (id === 'quiz') {
    if (S.gameplay === 'duel') {
      names = `
        <div class="set-label">玩法</div>
        <div class="chip-row"><span class="chip on">对战</span></div>
        <div class="sum-chips" id="playSum">${quizSumChips('duel')}</div>
        <div class="set-label">玩家昵称</div>
        <input id="duelName1" class="name-input" maxlength="8" placeholder="玩家一" value="${esc(S.p1)}">
        <input id="duelName2" class="name-input" maxlength="8" placeholder="玩家二" value="${esc(S.p2)}">`;
    } else {
      names = `
        <div class="set-label">玩法</div>
        <div class="chip-row" id="playChips">
          ${['speed', 'blitz'].map((p) => `<button class="chip${S.gameplay === p ? ' on' : ''}" data-p="${p}">${PLAY_NAMES[p]}</button>`).join('')}
        </div>
        <div class="sum-chips" id="playSum">${quizSumChips(S.gameplay)}</div>`;
    }
  } else chips = sumChips();
  const ov = openOverlay(`
    <button class="close-x" aria-label="关闭">${xIcon}</button>
    <div class="start-hero">
      <span class="micon ${m.hue}">${m.icon}</span>
      <div><h2 style="margin-bottom:2px">${mTitle}</h2><span class="p-sub" style="margin:0">${mSub}</span></div>
    </div>
    ${(id === 'quiz' || id === 'puzzle' || id === 'outline') ? names : `<div class="sum-chips">${chips}</div>`}
    <div class="btn-row">
      <button id="btnStart" class="btn-primary">开始游戏</button>
      <button id="btnAdj" class="btn-ghost">调整参数</button>
    </div>
  `);
  if (id === 'outline' && $('#olRounds', ov)) {
    $('#olRounds', ov).addEventListener('click', (e) => {
      const b = e.target.closest('.chip'); if (!b) return;
      S.outlineRounds = parseInt(b.dataset.v, 10); S.save();
      $$('.chip', $('#olRounds', ov)).forEach((c) => c.classList.toggle('on', c.dataset.v === b.dataset.v));
      Sound.click();
    });
  }
  function renderOlScoreParams() {
    const box = $('#olScoreParams', ov);
    if (!box) return;
    box.innerHTML = S.outlineMode === 'score' ? `
        <div class="set-label">初始分值</div>
        <div class="chip-row" id="olStart">
          ${[0,5,10].map((v)=>`<button class="chip${S.outlineStart===v?' on':''}" data-v="${v}">${v} 分</button>`).join('')}
        </div>
        <div class="set-label">答错扣分</div>
        <div class="chip-row" id="olPenalty">
          ${[0,0.5,1,2].map((v)=>`<button class="chip${S.outlinePenalty===v?' on':''}" data-v="${v}">${v===0?'不扣':'扣 '+v+' 分'}</button>`).join('')}
        </div>` : '';
    bindOlScoreParams();
  }
  renderOlScoreParams();
  if (id === 'outline' && $('#olMode', ov)) {
    $('#olMode', ov).addEventListener('click', (e) => {
      const b = e.target.closest('.chip'); if (!b) return;
      S.outlineMode = b.dataset.v; S.save();
      $$('.chip', $('#olMode', ov)).forEach((c) => c.classList.toggle('on', c.dataset.v === S.outlineMode));
      renderOlScoreParams();
      Sound.click();
    });
  }
  function bindOlScoreParams() {
    const el1 = $('#olStart', ov);
    if (el1) el1.addEventListener('click', (e) => {
      const b = e.target.closest('.chip'); if (!b) return;
      S.outlineStart = parseFloat(b.dataset.v); S.save();
      $$('.chip', el1).forEach((c) => c.classList.toggle('on', c.dataset.v === b.dataset.v));
      Sound.click();
    });
    const el2 = $('#olPenalty', ov);
    if (el2) el2.addEventListener('click', (e) => {
      const b = e.target.closest('.chip'); if (!b) return;
      S.outlinePenalty = parseFloat(b.dataset.v); S.save();
      $$('.chip', el2).forEach((c) => c.classList.toggle('on', c.dataset.v === b.dataset.v));
      Sound.click();
    });
  }
  bindOlScoreParams();
  if (id === 'quiz' && $('#playChips', ov)) {
    $('#playChips', ov).addEventListener('click', (e) => {
      const b = e.target.closest('.chip');
      if (!b) return;
      S.gameplay = b.dataset.p; S.save();
      $$('.chip', $('#playChips', ov)).forEach((c) => c.classList.toggle('on', c.dataset.p === S.gameplay));
      $('#playSum', ov).innerHTML = quizSumChips(S.gameplay);
      Sound.click();
    });
  }
  if (id === 'puzzle') {
    function renderPgParams() {
      let html = '';
      if (S.puzzleGame === 'race') {
        html = [5, 10, 15].map((v) => `<button class="chip${S.raceRounds === v ? ' on' : ''}" data-k="raceRounds" data-v="${v}">${v} 回合</button>`).join('');
      } else if (S.puzzleGame === 'split') {
        html = [6, 10, 14].map((v) => `<button class="chip${S.splitSize === v ? ' on' : ''}" data-k="splitSize" data-v="${v}">每方 ${v} 省</button>`).join('');
      }
      $('#pgParams', ov).innerHTML = html;
      $('#pgSum', ov).innerHTML = puzzleSumChips();
      $('#pgNames', ov).classList.toggle('hidden', !['race', 'split'].includes(S.puzzleGame));
    }
    $('#pgChips', ov).addEventListener('click', (e) => {
      const b = e.target.closest('.chip');
      if (!b) return;
      S.puzzleGame = b.dataset.p; S.save();
      $$('.chip', $('#pgChips', ov)).forEach((c) => c.classList.toggle('on', c.dataset.p === S.puzzleGame));
      renderPgParams();
      Sound.click();
    });
    $('#pgParams', ov).addEventListener('click', (e) => {
      const b = e.target.closest('.chip');
      if (!b) return;
      S[b.dataset.k] = parseInt(b.dataset.v, 10); S.save();
      $$('.chip', $('#pgParams', ov)).forEach((c) => c.classList.toggle('on', c.dataset.k === b.dataset.k && c.dataset.v === b.dataset.v));
      renderPgParams();
      Sound.click();
    });
    renderPgParams();
  }
  $('#btnStart', ov).addEventListener('click', () => {
    if ((id === 'quiz' && S.gameplay === 'duel') || (id === 'outline' && S.outlineGame === 'duel') || (id === 'puzzle' && ['race', 'split'].includes(S.puzzleGame))) {
      const n1 = $('#duelName1', ov).value.trim() || '玩家一';
      const n2 = $('#duelName2', ov).value.trim() || '玩家二';
      S.p1 = n1; S.p2 = n2; S.save();
    }
    Sound.init(); Sound.resume();
    closeOverlay();
    startMode(id);
  });
  $('#btnAdj', ov).addEventListener('click', () => { closeOverlay(); showSettings(); });
}
function startMode(id) {
  if (id === 'explore') Explore.start();
  else if (id === 'puzzle') Puzzle.start();
  else if (id === 'outline') Outline.start(S.outlineGame);
  else Game.startRound(id);
}

/* ================= 探索模式 ================= */
const Explore = {
  seen: new Set(Store.get('exploredNames', [])),
  start() {
    Game.enter('explore');
    Game._show('livesRow', false);
    Game._show('questionBar', true);
    $('#qTag').textContent = '自由探索';
    $('#qText').textContent = '点击任意省份，认识它的名称与风土';
    $('#qHints').innerHTML = '';
    $('#qProgress').textContent = '';
    $('#btnHint').style.display = 'none';
    ChinaMap.setInteraction({ labels: true, hover: true, onClick: (n) => this.showInfo(n), puzzleBase: 'normal' });
    ChinaMap.resetView(true);
    const legend = $('#legend');
    legend.classList.remove('hidden');
    legend.innerHTML = REGIONS.map((r) => `<span class="legend-chip"><i style="background:var(--c-${REGION_KEY[r]})"></i>${r}</span>`).join('');
    ChinaMap.bindHover();
    Game._show('hudTimer', false);
    $('#hudScore').textContent = '';
  },
  showInfo(name) {
    const p = CHINA_DATA.provinces.find((x) => x.name === name);
    if (!p) return;
    if (!this.seen.has(name)) {
      this.seen.add(name);
      Store.set('exploredNames', Array.from(this.seen));
    }
    const card = $('#infoCard');
    card.innerHTML = `
      <div class="ic-top">
        <span class="ic-short">${p.short}</span>
        <h3>${p.name}</h3>
        <span class="ic-region">${p.region}</span>
      </div>
      <div class="ic-stats">
        <div class="ic-stat"><b>${p.capital}</b><span>省会</span></div>
        <div class="ic-stat"><b class="num">${p.area.toLocaleString()}</b><span>面积 km²</span></div>
        <div class="ic-stat"><b class="num">${(p.pop / 10000).toFixed(2)}</b><span>人口 亿</span></div>
      </div>
      <div class="ic-actions">
        <button class="btn-primary" id="icQuiz">考考我</button>
        <button class="btn-ghost" id="icClose">收起</button>
      </div>`;
    card.classList.remove('hidden');
    $('#icClose', card).addEventListener('click', () => card.classList.add('hidden'));
    $('#icQuiz', card).addEventListener('click', () => {
      card.classList.add('hidden');
      Sound.click();
      Game.startRound('quiz');
    });
  },
};

/* ================= 结果弹窗 ================= */
const Result = {
  _pending: null,
  show(data) {
    Game._show('livesRow', false);
    if (Game.mode === 'puzzle') Puzzle.cleanup();
    const pct = Math.round((data.acc || 0) * 100);
    const play = data.play;
    const isDuel = play === 'duel' || !!data.duel;
    const rName = data.duel ? (data.title || '双人比拼') : play === 'duel' ? '双人对战' : play === 'blitz' ? '限时冲刺' : (data.title || '本局');
    let html = `<div class="result">
      <div class="r-label">${rName}</div>
      <div class="r-score num">${data.score}</div>`;

    if (isDuel) {
      const w0 = data.winner === 0, w1 = data.winner === 1;
      html += `<div class="duel-result">
        <div class="dr-p ${w0 ? 'win' : ''}"><div class="nm">${esc(data.p1.name)}</div><div class="sc num">${data.p1.time !== undefined ? fmtTime(data.p1.time) : data.p1.score}</div><div class="tag">${w0 ? '胜者' : ''}</div></div>
        <div class="dr-p ${w1 ? 'win' : ''}"><div class="nm">${esc(data.p2.name)}</div><div class="sc num">${data.p2.time !== undefined ? fmtTime(data.p2.time) : data.p2.score}</div><div class="tag">${w1 ? '胜者' : ''}</div></div>
      </div>`;
    } else {
      html += `<div class="r-grid">
        <div class="r-cell"><b class="num">${pct}%</b><span>正确率</span></div>
        <div class="r-cell"><b class="num">${fmtTime(data.time)}</b><span>用时</span></div>
        <div class="r-cell"><b class="num">${data.maxCombo || 0}</b><span>最高连击</span></div>
        <div class="r-cell"><b class="num">${data.minReact ? data.minReact + 's' : '—'}</b><span>最快单题</span></div>
      </div>`;
    }

    html += `<div class="btn-row" style="margin-top:14px">
      <button id="btnAgain" class="btn-primary">${isDuel ? '再战一局' : '再玩一局'}</button>
      <button id="btnHome" class="btn-ghost">返回首页</button>
    </div>`;
    html += `</div>`;
    const host = $('#modalHost');
    host.innerHTML = '<div class="overlay"><div class="panel">' + html + '</div></div>';
    const ov = $('.overlay', host);
    ov.addEventListener('pointerdown', (e) => { if (e.target === ov) return; });
    const mode = data.mode;
    $('#btnAgain', ov).addEventListener('click', () => {
      host.innerHTML = '';
      startMode(mode === 'puzzle' ? 'puzzle' : mode);
    });
    $('#btnHome', ov).addEventListener('click', () => {
      host.innerHTML = '';
      Game.quit();
    });
  },
};

/* ================= 排行榜 / 成就 / 帮助 ================= */

function showHelp() {
  openOverlay(`
    <button class="close-x" aria-label="关闭">${xIcon}</button>
    <h2>玩法说明</h2>
    <p class="p-sub">四种模式 · 三种玩法</p>
    ${MODES.map((m) => `<div class="ach-item"><span class="a-icon ${m.hue}">${m.icon}</span><div><div class="a-t">${m.name}</div><div class="a-d">${m.desc}</div></div></div>`).join('')}
    <div class="set-sep"></div>
    <div class="set-label">地图操作</div>
    <div class="a-d" style="line-height:1.8;margin-bottom:8px">
      · 拖动地图：单指/鼠标拖拽<br>
      · 缩放：双指捏合、滚轮，或右下角 ＋ － 按钮<br>
      · 点击省份：作答 / 查看信息<br>
      · 答题模式可点击「提示」逐级揭晓：区域 → 省会 → 直接定位
    </div>
  `);
}
'use strict';
/* ================= 初始化与全局接线 ================= */
function updateSoundIcon() {
  const b = $('#btnSound');
  b.classList.toggle('sound-off', !Sound.isOn());
}
function toggleFull() {
  if (document.fullscreenElement) {
    document.exitFullscreen().catch(() => {});
  } else if (document.documentElement.requestFullscreen) {
    document.documentElement.requestFullscreen().catch(() => {});
  }
}
let iosTipped = false;
function maybeIosTip() {
  if (iosTipped || !/iP(hone|ad|od)/.test(navigator.userAgent)) return;
  iosTipped = true;
  Sound.probeSilence((silent) => {
    if (!silent) return;
    const tip = document.createElement('div');
    tip.className = 'ios-tip';
    tip.innerHTML = '<svg viewBox="0 0 24 24" style="width:13px;height:13px;stroke:currentColor;fill:none;stroke-width:2"><path d="M15 8a4 4 0 0 1 0 8"/><path d="M4 9v6h4l5 4V5L8 9H4z"/></svg>iPhone 请关闭侧边静音键以收听音效';
    document.body.appendChild(tip);
    setTimeout(() => tip.remove(), 9000);
  });
}

function wireTopbar() {
  $('#btnBrand').addEventListener('click', () => { Sound.click(); openBrand(); });
  $('#btnRestart').addEventListener('click', () => { Sound.click(); Game.resetRound(); });
  $('#btnBack').addEventListener('click', () => { Sound.click(); Game.quit(); });
  $('#btnSound').addEventListener('click', () => {
    Sound.init(); Sound.resume();
    Sound.toggle();
    updateSoundIcon();
    Sound.click();
    toast(Sound.isOn() ? '音效已开启' : '音效已关闭');
  });
  $('#btnTheme').addEventListener('click', () => {
    Sound.init();
    Theme.cycle();
  });
  $('#btnSettings').addEventListener('click', () => { Sound.init(); Sound.click(); showSettings(); });
  $('#btnFull').addEventListener('click', () => { Sound.click(); toggleFull(); });
  $('#btnHint').addEventListener('click', () => {
    Sound.click();
    if (Game.mode === 'puzzle') Puzzle.useHint();
    else Game.useHint();
  });
  $('#btnHelp').addEventListener('click', () => { Sound.click(); showHelp(); });
}
function wireZoom() {
  $('#zoomIn').addEventListener('click', () => { Sound.click(); ChinaMap.zoomBy(1.45); });
  $('#zoomOut').addEventListener('click', () => { Sound.click(); ChinaMap.zoomBy(1 / 1.45); });
  $('#zoomReset').addEventListener('click', () => { Sound.click(); ChinaMap.resetView(); });
}

function boot() {
  Theme.apply();
  Sound.setOn(Store.get('sound', true));
  if (S.sfx === false) Sound.setOn(false);
  document.body.classList.toggle('anim-off', !!S.anim);
  updateSoundIcon();
  ChinaMap.build();
  ChinaMap.bindHover();
  renderHome();
  wireTopbar();
  wireZoom();
  document.addEventListener('pointerdown', function first() {
    Sound.init(); Sound.resume();
    maybeIosTip();
  }, { once: true, passive: true });
  window.addEventListener('resize', debounce(() => {
    ChinaMap.applyTransform();
    ChinaMap.layoutLabels();
  }, 160));
  requestAnimationFrame(() => ChinaMap.layoutLabels());
}
boot();
